const startsOfSegments = `-- name: StartsOfSegments :many
SELECT h.id AS highlight_id, coalesce((SELECT sg.start_ms FROM segment sg WHERE sg.source_item_id = h.source_item_id AND sg.span_start <= h.span_start ORDER BY sg.span_start DESC LIMIT 1), -1)::int AS start_ms
FROM highlight h WHERE h.workspace_id = $1 AND h.id = ANY ($2::uuid[])
`

type StartsOfSegmentsParams struct {
	WorkspaceID uuid.UUID
	Ids         []uuid.UUID
}

type StartsOfSegmentsRow struct {
	HighlightID uuid.UUID
	StartMs     int32
}

func (q *Queries) StartsOfSegments(ctx context.Context, arg StartsOfSegmentsParams) ([]StartsOfSegmentsRow, error) {
	rows, err := q.db.Query(ctx, startsOfSegments, arg.WorkspaceID, arg.Ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []StartsOfSegmentsRow
	for rows.Next() {
		var i StartsOfSegmentsRow
		if err := rows.Scan(&i.HighlightID, &i.StartMs); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const sumMediaBytesSince = `-- name: SumMediaBytesSince :one
SELECT coalesce(sum(size_bytes), 0)::bigint FROM media WHERE workspace_id = $1 AND created_at >= $2
`

type SumMediaBytesSinceParams struct {
	WorkspaceID uuid.UUID
	CreatedAt   time.Time
}

func (q *Queries) SumMediaBytesSince(ctx context.Context, arg SumMediaBytesSinceParams) (int64, error) {
	row := q.db.QueryRow(ctx, sumMediaBytesSince, arg.WorkspaceID, arg.CreatedAt)
	var column_1 int64
	err := row.Scan(&column_1)
	return column_1, err
}
